const taxonomy = {
  'postgresql': 'SQL validé (SGBDR relationnel)',
  'mysql': 'SQL validé (SGBDR relationnel)',
  'scikit-learn': 'Machine Learning Python validé',
  'pandas': 'Data Manipulation Python validé',
  'docker': 'Conteneurisation (notions)',
  'git': 'Version control standard'
};
let match = 'Technologie standard sans équivalence directe';
