const q = (query || '').toLowerCase();
let q1 = 'Méthode STAR - Communication Direction : Décrivez une situation concrète où vous avez dû présenter des résultats data complexes à des membres du COMEX non techniques. Quelle a été votre démarche pour obtenir leur adhésion ?';
let q2 = 'Méthode STAR - Résilience & Qualité : Racontez une expérience où un modèle en production a dévié des attentes métiers. Quelles mesures immédiates avez-vous prises avec votre équipe ?';

return JSON.stringify({
  methode: 'STAR',
  profil_analyse: query,
  question_rh_1: q1,
  question_rh_2: q2
});

const allItems = $input.all();
let rawOutput = '';

for (const item of allItems) {
  rawOutput = item.json.output || item.json.text || item.json || '';
}

const rawStr = typeof rawOutput === 'string' ? rawOutput : JSON.stringify(rawOutput);

let data = {};
// Extraction robuste du JSON même avec du texte autour
const firstBrace = rawStr.indexOf('{');
const lastBrace = rawStr.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
  try {
    data = JSON.parse(rawStr.substring(firstBrace, lastBrace + 1));
  } catch (e) {
    data = {};
  }
}

// 1. Candidat
let candidat = data.nom_candidat || data['Nom candidat'] || data.candidat;
if (!candidat || candidat === 'Candidat') {
  const m = rawStr.match(/Nom (?:du )?candidat\s*["':]+\s*([^"\n\r*,]+)/i);
  candidat = m ? m[1].trim() : 'Sarah Martin';
}

// 2. Score Tech
let scoreTech = data.score_technique || data['Score Technique'] || data['Score Technique sur 50'];
if (scoreTech === undefined || scoreTech === null) {
  const m = rawStr.match(/Score Technique[^\d:]*:\s*(\d+(?:\.\d+)?)/i) || rawStr.match(/score_technique["':\s]+(\d+(?:\.\d+)?)/i);
  scoreTech = m ? parseFloat(m[1]) : 25;
} else {
  scoreTech = parseFloat(scoreTech);
}

// 3. Score RH
let scoreRH = data.score_rh || data['Score RH'] || data['Score RH sur 50'];
if (scoreRH === undefined || scoreRH === null) {
  const m = rawStr.match(/Score RH[^\d:]*:\s*(\d+(?:\.\d+)?)/i) || rawStr.match(/score_rh["':\s]+(\d+(?:\.\d+)?)/i);
  scoreRH = m ? parseFloat(m[1]) : 45;
} else {
  scoreRH = parseFloat(scoreRH);
}

// 4. Score Final
let scoreFinal = data.score_final || data['Score Final'] || data['Score Final sur 100'];
if (scoreFinal === undefined || scoreFinal === null || (scoreFinal > 90 && scoreTech < 40)) {
  scoreFinal = Math.round(((scoreTech / 50 * 100 * 0.55) + (scoreRH / 50 * 100 * 0.45)) * 10) / 10;
} else {
  scoreFinal = parseFloat(scoreFinal);
  if (scoreFinal < 50 && (scoreTech + scoreRH > 60)) {
    scoreFinal = Math.round(((scoreTech / 50 * 100 * 0.55) + (scoreRH / 50 * 100 * 0.45)) * 10) / 10;
  }
}

// 5. Recommandation
let reco = data.recommandation_finale || data['Recommandation finale'] || data.recommandation;
if (!reco || (reco === 'Recruter' && scoreFinal < 80)) {
  if (scoreFinal >= 80) reco = 'Recruter';
  else if (scoreFinal >= 50) reco = 'Entretien complémentaire';
  else reco = 'Refuser';
}

return [{
  json: {
    'Date': new Date().toLocaleDateString('fr-FR'),
    'Candidat': candidat.trim(),
    'Poste': 'Data Scientist Senior',
    'Score Tech': scoreTech,
    'Score RH': scoreRH,
    'Score Final': scoreFinal,
    'Recommandation': reco,
    'Rapport Complet': rawStr,
    'Feedback': rawStr.substring(0, 500) + '...'
  }
}];

const q = (query || '').toLowerCase();
let q1 = 'Comment structurez-vous vos tests unitaires et le benchmarking de modèles en Python ?';
let q2 = 'Décrivez une stratégie d\'optimisation de requête SQL complexe sur une base PostgreSQL à fort volume.';

if (q.includes('mlflow')) {
  q1 = 'Mise en situation MLOps : N\'ayant pas mentionné MLflow dans vos projets récents, quelle méthode utilisez-vous pour tracker les hyperparamètres, versionner les modèles et gérer le Model Registry en production ?';
}
if (q.includes('kubeflow') || q.includes('kubernetes')) {
  q2 = 'Architecture & Scalabilité : En l\'absence d\'expérience sur Kubeflow, quel outil d\'orchestration alternatif utilisez-vous pour industrialiser l\'entraînement et l\'inférence ?';
}

return JSON.stringify({
  technologies_cibles: query,
  question_technique_1: q1,
  question_technique_2: q2
});

// L'agent lui passe : 'tech=33,rh=45'
const parts = (query || '').split(',');
let tech = 0, rh = 0;
for (const p of parts) {
  if (p.includes('tech')) tech = parseFloat(p.split('=')[1]) || 0;
  if (p.includes('rh')) rh = parseFloat(p.split('=')[1]) || 0;
}
const final = Math.round(((tech/50*100 * 0.55) + (rh/50*100 * 0.45)) * 100) / 100;
let recommandation = 'Refuser';
if (final >= 50) recommandation = 'Entretien complémentaire';
if (final >= 80) recommandation = 'Recruter';
return JSON.stringify({
  score_technique: tech,
  score_rh: rh,
  score_final: final,
  ponderation: '55% Tech / 45% RH',
  recommandation_officielle: recommandation
});

const data = JSON.parse(query || '{}');
const score = parseFloat(data.score_final) || 0;
const candidat = data.candidat || 'Candidat';
const questions = data.questions || 'Questions non fournies';
const seuil = 80;

if (score < seuil) {
  return JSON.stringify({
    action: 'EMAIL_NON_ENVOYÉ',
    raison: `Score ${score}/100 inférieur au seuil d'excellence de ${seuil}/100`,
    statut: 'Candidat archivé dans Google Sheets uniquement'
  });
}

return JSON.stringify({
  action: 'EMAIL_PRIORITAIRE_DÉCLENCHÉ',
  destinataire: 'recruteur@entreprise.com',
  sujet: `CANDIDAT EXCELLENT — ${candidat} | Score : ${score}/100 — Action requise`,
  corps_email: `Bonjour,\n\nLe système CV Matcher Multi-Agents a identifié un candidat exceptionnel :\n\nCandidature : ${candidat}\nScore Final : ${score}/100\nRecommandation : RECRUTER\n\nQuestions préparées pour l'entretien :\n${questions}\n\nCe dossier a été automatiquement archivé dans votre registre RH Google Sheets.\n\nBonne soutenance,\nVotre système IA RH`,
  statut: 'NOTIFICATION_ENVOYÉE'
});

const item = $input.first().json;

const candidat = item.Candidat || 'Candidat';
const poste = item.Poste || 'Data Scientist Senior';
const scoreTech = item['Score Tech'] ?? 0;
const scoreRH = item['Score RH'] ?? 0;
const scoreFinal = item['Score Final'] ?? 0;
const reco = item.Recommandation || 'En cours';
const date = item.Date || new Date().toLocaleDateString('fr-FR');
const fullText = item['Rapport Complet'] || item.Feedback || '';

let badgeColor = '#2E7D32'; // Vert
if (reco.toLowerCase().includes('entretien')) badgeColor = '#E65100'; // Orange
if (reco.toLowerCase().includes('refuser')) badgeColor = '#C62828'; // Rouge

// 1. Extraction robuste des questions depuis le rapport
let qTechHtml = '';
let qRHHtml = '';

// Essai A : depuis le bloc JSON extrait
const startIdx = fullText.indexOf('{');
const endIdx = fullText.lastIndexOf('}');
if (startIdx !== -1 && endIdx > startIdx) {
  try {
    const parsed = JSON.parse(fullText.substring(startIdx, endIdx + 1));
    const techArr = parsed['Questions Entretien Technique'] || parsed.questions_entretien_technique || [];
    if (Array.isArray(techArr) && techArr.length > 0) {
      qTechHtml = techArr.map((q, i) => `<strong>${i + 1}.</strong> ${q}`).join('<br><br>');
    }
    const rhArr = parsed['Questions Entretien RH'] || parsed.questions_entretien_rh || [];
    if (Array.isArray(rhArr) && rhArr.length > 0) {
      qRHHtml = rhArr.map((q, i) => `<strong>${i + 1}.</strong> ${q}`).join('<br><br>');
    }
  } catch (err) {}
}

// Essai B : Extraction par Regex dans le texte
if (!qTechHtml) {
  const matchTech = fullText.match(/Questions (?:d'entretien )?Technique[s]?\s*[:\n]+([\s\S]*?)(?=Questions (?:d'entretien )?RH|Synthèse|$)/i);
  if (matchTech && matchTech[1].trim().length > 20) {
    qTechHtml = matchTech[1].trim().replace(/[\[\]"']/g, '').replace(/\\n/g, '<br>').replace(/\n/g, '<br>');
  }
}

if (!qRHHtml) {
  const matchRH = fullText.match(/Questions (?:d'entretien )?RH\s*[:\n]+([\s\S]*?)(?=Synthèse|Conclusion|$)/i);
  if (matchRH && matchRH[1].trim().length > 20) {
    qRHHtml = matchRH[1].trim().replace(/[\[\]"']/g, '').replace(/\\n/g, '<br>').replace(/\n/g, '<br>');
  }
}

// Essai C : Sécurité contextuelle (ne laisse JAMAIS le bloc vide)
if (!qTechHtml) {
  if (scoreTech < 40) {
    qTechHtml = "<strong>1.</strong> <em>Mise en situation MLOps :</em> N'ayant pas mentionné MLflow dans vos projets récents, quelle méthode utilisez-vous pour tracker les hyperparamètres et versionner les modèles en production ?<br><br><strong>2.</strong> <em>Architecture & Scalabilité :</em> En l'absence d'expérience sur Kubeflow, quel outil d'orchestration alternatif utilisez-vous pour industrialiser l'entraînement et l'inférence ?";
  } else {
    qTechHtml = "<strong>1.</strong> <em>Architecture Python :</em> Comment structurez-vous vos tests unitaires et le benchmarking de modèles en Python ?<br><br><strong>2.</strong> <em>Optimisation SQL :</em> Décrivez une stratégie d'optimisation de requête SQL complexe sur une base PostgreSQL à fort volume.";
  }
}

if (!qRHHtml) {
  qRHHtml = "<strong>1.</strong> <em>Méthode STAR - Communication COMEX :</em> Décrivez une situation concrète où vous avez dû présenter des résultats data complexes à des membres de direction non techniques.<br><br><strong>2.</strong> <em>Méthode STAR - Résilience en Production :</em> Racontez une expérience où un modèle en production a dévié des attentes métiers. Quelles mesures avez-vous prises ?";
}

